SELECT item_id,version,CAST(json_object('kind',target_kind,'value',json(CASE target_kind WHEN 'peer' THEN json_object('peer',machine_id,'route',json(status_route)) WHEN 'statusStream' THEN json_object('route',json(status_route),'sender',machine_id) END)) AS TEXT) AS target,CAST(json_object('item',item_id,'status',json(CASE status_kind WHEN 'delivered' THEN json_object('kind',status_kind,'value',json_object('acceptance',json(status_acceptance))) WHEN 'refused' THEN json_object('kind',status_kind,'value',json_object('reason',json(CASE refusal_kind WHEN 'recipientRefused' THEN json_object('kind',refusal_kind,'value',json_object('code',refusal_code)) WHEN 'processingFailed' THEN json_object('kind',refusal_kind,'value',json_object('kind',refusal_failure)) WHEN 'tooLarge' THEN json_object('kind',refusal_kind,'value',json_object('field',refusal_size_field)) WHEN 'itemConflict' THEN json_object('kind',refusal_kind,'value',json_object('existing',refusal_digest)) WHEN 'cancelAlreadyRequested' THEN json_object('kind',refusal_kind,'value',json_object('existing',json_object('item',refusal_item_id,'digest',refusal_digest))) ELSE json_object('kind',refusal_kind) END))) ELSE json_object('kind',status_kind) END),'version',version,'cancel',json(CASE cancel_outcome WHEN 'tooLate' THEN json_object('kind',cancel_outcome,'value',json_object('at',cancel_too_late_at)) WHEN NULL THEN NULL ELSE CASE WHEN cancel_outcome IS NULL THEN NULL ELSE json_object('kind',cancel_outcome) END END)) AS TEXT) AS record FROM _fleet_sync_status_owed ORDER BY item_id,version;
